import{G as e,W as t,rt as n,t as r}from"./chunks/framework.3zKPIMIf.js";var i=JSON.parse(`{"title":"プライバシーポリシー","description":"","frontmatter":{},"headers":[],"relativePath":"ja/privacy-policy.md","filePath":"ja/privacy-policy.md"}`),a={name:`ja/privacy-policy.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="プライバシーポリシー" tabindex="-1">プライバシーポリシー <a class="header-anchor" href="#プライバシーポリシー" aria-label="Permalink to “プライバシーポリシー”">​</a></h1><p>cBlockはデータを一切収集しません。</p><ul><li>cBlockはサーバーを使用しません。</li><li>ページのテキストはブラウザの中だけで読み取り、cBlockの開発者を含めどこにも送信しません。</li><li>設定と問い合わせの結果はブラウザの中だけに保存し、拡張機能を削除すると消去します。</li></ul><h2 id="webサイトへの問い合わせ" tabindex="-1">Webサイトへの問い合わせ <a class="header-anchor" href="#webサイトへの問い合わせ" aria-label="Permalink to “Webサイトへの問い合わせ”">​</a></h2><p>設定ページの「Webサイトへの問い合わせ」のいずれかをオンにすると、より正確に判定するために表示中のページの項目についてそのWebサイトに問い合わせます。</p><p>例えば、Amazonの検索結果には出品者の所在地が、Steamの検索結果には開発元やパブリッシャーが表示されません。同様に、Xのポストには投稿者の所在地が、pixivの作品には作者の所在地が表示されません。そのため、ページに表示されていない情報をそのWebサイトに問い合わせて判定します。</p><p><strong>これらの機能はいずれも初期設定ではオフです。</strong></p><table tabindex="0"><thead><tr><th>Webサイト</th><th>cBlockが送信するもの</th><th>理由</th><th>送信先</th></tr></thead><tbody><tr><td><strong>Amazon</strong></td><td>商品IDと出品者ID</td><td>出品者の住所、電話番号、および名前を調べるため</td><td>表示中のAmazonのWebサイト</td></tr><tr><td><strong>Steam</strong></td><td>ゲームID</td><td>開発元とパブリッシャーを調べるため</td><td><code>store.steampowered.com</code></td></tr><tr><td><strong>X</strong></td><td>表示中のポストのユーザー名</td><td>投稿者のアカウントの所在地と接続元を調べるため</td><td><code>x.com</code></td></tr><tr><td><strong>pixiv</strong></td><td>表示中の作品の作者ID</td><td>作者のプロフィールを調べるため</td><td><code>www.pixiv.net</code></td></tr></tbody></table><ul><li>問い合わせは表示中のWebサイトに対してのみ行い、cBlockの開発者や第三者には何も送信しません。</li><li>同じ問い合わせを繰り返さないよう、問い合わせの結果はブラウザに30日間保存します。</li></ul>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};